import template from "./template.hbs";

const input = document.getElementById("bookmarkInput");
const addBtn = document.getElementById("addBookmarkBtn");
const list = document.getElementById("bookmarkList");

let bookmarks = JSON.parse(localStorage.getItem("bookmarks")) || [];

function saveBookmarks() {
  localStorage.setItem("bookmarks", JSON.stringify(bookmarks));
}

function renderBookmarks() {
  list.innerHTML = "";

  bookmarks.forEach((url, index) => {
    const li = document.createElement("li");

    const link = document.createElement("a");
    link.href = url;
    link.textContent = url;
    link.target = "_blank";

    const delBtn = document.createElement("button");
    delBtn.textContent = "X";
    delBtn.classList.add("delete");

    delBtn.onclick = () => {
      bookmarks.splice(index, 1);
      saveBookmarks();
      renderBookmarks();
    };

    link.ondblclick = () => {
      const newUrl = prompt("Новий URL:", url);
      if (newUrl) {
        bookmarks[index] = newUrl;
        saveBookmarks();
        renderBookmarks();
      }
    };

    li.append(link, delBtn);
    list.appendChild(li);
  });
}

addBtn.onclick = () => {
  if (!input.value.trim()) return;

  bookmarks.push(input.value.trim());
  input.value = "";
  saveBookmarks();
  renderBookmarks();
};

renderBookmarks();

const username = document.getElementById("username");
const password = document.getElementById("password");
const saveBtn = document.getElementById("saveBtn");

function loadForm() {
  const data = JSON.parse(localStorage.getItem("formData"));
  if (data) {
    username.value = data.username || "";
    password.value = data.password || "";
  }
}

saveBtn.onclick = () => {
  const data = {
    username: username.value,
    password: password.value,
  };
  localStorage.setItem("formData", JSON.stringify(data));
};

loadForm();

const products = [
  { name: "Laptop", price: 1200, description: "Powerful laptop" },
  { name: "Phone", price: 800, description: "Smartphone" },
  { name: "Headphones", price: 200, description: "Noise cancelling" },
];

const container = document.getElementById("products");
const search = document.getElementById("search");

function renderProducts(data) {
  container.innerHTML = template(data);
}

search.addEventListener("input", (e) => {
  const value = e.target.value.toLowerCase();

  const filtered = products.filter((p) => p.name.toLowerCase().includes(value));

  renderProducts(filtered);
});

renderProducts(products);
